{"code":"import random

def vary(example, rng):
    # Generate a checkerboard-like field, then erase several rectangular regions;
    # the transformation is expected to reconstruct the regular field.
    h = rng.randint(11, 30)
    w = rng.randint(11, 30)
    grid = []
    for r in range(h):
        row = []
        for c in range(w):
            if r % 2 == 0:
                row.append(3 if c % 2 == 0 else 2)
            else:
                row.append(2 if c % 2 == 0 else 1)
        grid.append(row)
    # Erase compact, nontrivial rectangular patches, as in the example.
    n = rng.randint(1, 4)
    for _ in range(n):
        rh = rng.randint(1, max(1, min(7, h // 2)))
        rw = rng.randint(1, max(1, min(7, w // 2)))
        r0 = rng.randint(0, h-rh)
        c0 = rng.randint(0, w-rw)
        for r in range(r0, r0+rh):
            for c in range(c0, c0+rw):
                grid[r][c] = 0
    return grid

def generate(rng):
    return vary([], rng)
"}

